class BirdRecord:
    def summary(self):
        return "조류 4마리"

class WeatherRecord:
    def summary(self):
        return "날씨 맑음"

for record in [BirdRecord(), WeatherRecord()]:
    print(record.summary())

def render(record):
    return "기록: " + record.summary()

class CountRecord:
    def __init__(self, count):
        self.count = count
    def summary(self):
        return f"{self.count}개"

class NoteRecord:
    def summary(self):
        return "수량 확인 전"

print(render(CountRecord(5)))
print(render(NoteRecord()))
